package dev.sfstudio.watchdog.application;

import dev.sfstudio.watchdog.alert.*; import dev.sfstudio.watchdog.health.*; import dev.sfstudio.watchdog.journal.*; import dev.sfstudio.watchdog.observation.*; import dev.sfstudio.watchdog.persistence.WatchDogRepository; import dev.sfstudio.watchdog.snapshot.*; import dev.sfstudio.watchdog.watch.*; import java.time.Instant; import java.util.*;
public final class WatchDogApplicationService {
 private final ObservationService observations; private final SnapshotFactory snapshots; private final HealthEngine health; private final WatchEngine watch; private final AlertEngine alerts; private final WatchDogRepository repository;
 public WatchDogApplicationService(ObservationService observations, SnapshotFactory snapshots, HealthEngine health, WatchEngine watch, AlertEngine alerts, WatchDogRepository repository){this.observations=observations;this.snapshots=snapshots;this.health=health;this.watch=watch;this.alerts=alerts;this.repository=repository;}
 public MonitoringRun monitor(ObservationRequest request, List<WatchRule> rules, String snapshotId, Instant eventAt){ Observation o=observations.execute(request); DeviceSnapshot s=snapshots.from(snapshotId,o); repository.saveSnapshot(s); repository.appendJournal(new JournalEntry("journal:"+snapshotId,JournalEventType.SNAPSHOT_CREATED,eventAt,s.snapshotId(),request.requestId(),"Snapshot created")); List<HealthFinding> fs=health.evaluate(s); List<Alert> out=new ArrayList<>(); int i=0; for(HealthFinding f:fs) for(WatchRule r:rules){WatchEvaluation e=watch.evaluate(r,f); if(e.matched()){ Alert a=alerts.create("alert:"+snapshotId+":"+(++i),r,e,f,eventAt); repository.saveAlert(a); repository.appendJournal(new JournalEntry("journal:"+a.alertId(),JournalEventType.ALERT_OPENED,eventAt,a.alertId(),request.requestId(),a.reasonCode())); out.add(a); }} return new MonitoringRun(s,fs,out); }
}
